import os
import json
from pathlib import Path

# First, let's check what files are available in the current directory
print("Available files in current directory:")
for file in os.listdir('.'):
    if file.endswith('.json') or file.endswith('.txt') or file.endswith('.md'):
        print(f"  - {file}")

# Let's look for policy documents
policy_files = []
for file in os.listdir('.'):
    if 'policy' in file.lower() or 'terms' in file.lower():
        policy_files.append(file)

print(f"\nFound {len(policy_files)} potential policy files:")
for file in policy_files:
    print(f"  - {file}")

# Read the policy files
policies = {}
for file in policy_files:
    try:
        with open(file, 'r', encoding='utf-8') as f:
            content = f.read()
            policies[file] = content
            print(f"\n=== Content of {file} (first 500 chars) ===")
            print(content[:500])
    except Exception as e:
        print(f"Error reading {file}: {e}")
